import numpy as np, itertools, sys
L=open(sys.argv[1]).read().split('\n'); n=int(L[0]); P=[];S=[]
for l in L[2:2+n]:
    p=l.split(); S.append(p[0]); P.append([float(x) for x in p[1:4]])
P=np.array(P)
def ang(a,b,c):
    v1=P[a]-P[b]; v2=P[c]-P[b]
    return np.degrees(np.arccos(v1@v2/np.linalg.norm(v1)/np.linalg.norm(v2)))
for Ru,don in [(86,[26,27,2,90,88,89]),(87,[24,15,14,96,88,89])]:
    print('Ru',Ru)
    for a,b in itertools.combinations(don,2):
        print('  ',a,b,round(ang(a,Ru,b),1))
